import gleam/option.{type Option}

pub type Request {
  Request(
    method: String,
    url: String,
    headers: List(#(String, String)),
    body: BitArray,
  )
}

pub type Response {
  Response(status: Int, headers: List(#(String, String)), body: BitArray)
}

pub opaque type HttpCapability {
  HttpCapability(token: BitArray)
}

pub opaque type ClusterCapability {
  ClusterCapability(token: BitArray)
}

pub opaque type LogCapability {
  LogCapability(token: BitArray)
}

pub opaque type KvCapability {
  KvCapability(token: BitArray)
}

pub type Context {
  Context(
    cluster: ClusterCapability,
    http: Option(HttpCapability),
    log: LogCapability,
    kv: Option(KvCapability),
    deadline_unix_ms: Int,
  )
}

pub fn text(status: Int, body: String) -> Response {
  Response(
    status: status,
    headers: [
      #("content-type", "text/plain; charset=utf-8"),
    ],
    body: <<body:utf8>>,
  )
}

import bmscl.{type Context, type Request, type Response, Context, Request, Response}
import gleam/option.{None, Some}

pub fn handle(request: Request, context: Context) -> Response {
  let Request(method, url, _headers, body) = request
  let Context(_cluster, http, _log, kv, deadline_unix_ms) = context
  let capability_shape = case #(http, kv) {
    #(Some(_), None) -> "http-only"
    #(Some(_), Some(_)) -> "http+kv"
    #(None, Some(_)) -> "kv-only"
    #(None, None) -> "core-only"
  }

  Response(
    status: 201,
    headers: [
      #("x-method", method),
      #("x-url", url),
      #("x-capabilities", capability_shape),
      #("x-deadline", int_to_string(deadline_unix_ms)),
    ],
    body: body,
  )
}

fn int_to_string(value: Int) -> String {
  case value {
    123 -> "123"
    _ -> "other"
  }
}
